 for(unsigned i=0;i<32;i++){struct GNUNET_SCHEDULER_Task*t=h->backoff_task;assert(t&&t->active);printf("backoff|%u|%"PRIu64"|%"PRIu64"\n",i,t->delay,t->at);if(i==31)connector_available=1;deliver(t,0);}
 assert(h->mq&&h->current&&!h->backoff_task);complete_mq_head(h->mq);assert(h->backoff.rel_value_us==900000000);struct GNUNET_STATISTICS_ReplyMessage*reply;struct GNUNET_MQ_Envelope*row=GNUNET_MQ_msg_extra(reply,4,GNUNET_MESSAGE_TYPE_STATISTICS_VALUE);reply->uid=htonl(7);reply->value=GNUNET_htonll(9);memcpy(&reply[1],"s\0a\0",4);assert(check_statistics_value(h,reply)==GNUNET_OK);handle_statistics_value(h,reply);GNUNET_MQ_discard(row);assert(h->backoff.rel_value_us==900000000&&completion_calls==0);printf("progress-keeps-backoff|%"PRIu64"\n",h->backoff.rel_value_us);struct GNUNET_MessageHeader end={htons(4),htons(171)};handle_statistics_end(h,&end);assert(completion_calls==1&&completion_result==GNUNET_OK&&h->backoff.rel_value_us==1000);do_disconnect(h);reconnect_later(h);printf("end-reset|%"PRIu64"|%u|%d\n",h->backoff_task->delay,completion_calls,completion_result);GNUNET_STATISTICS_destroy(h,GNUNET_NO);
