 clock_now=31300;mq_error_handler(h,GNUNET_MQ_ERROR_WRITE);assert(!deadline->active&&mq_destroy_calls==1);printf("destroy-loss-cancel|%d|%u\n",deadline->active,mq_destroy_calls);
