static void overflow_clock(struct GNUNET_CONFIGURATION_Handle*cfg){reset("overflow");clock_now=UINT64_MAX-100;struct GNUNET_STATISTICS_Handle*h=GNUNET_STATISTICS_create("s",cfg);h->mq=queue();GNUNET_MQ_send(h->mq,envelope(168));GNUNET_STATISTICS_destroy(h,GNUNET_YES);assert(h->destroy_task->at==UINT64_MAX&&h->destroy_task->delay==5000);printf("clock-overflow|%"PRIu64"|%"PRIu64"\n",h->destroy_task->delay,h->destroy_task->at);h->do_destroy=GNUNET_NO;GNUNET_SCHEDULER_cancel(h->destroy_task);h->destroy_task=NULL;GNUNET_STATISTICS_destroy(h,GNUNET_NO);}
static void io_case(const char*name,ssize_t first,int err){
 reset(name);clock_now=0;struct ClientState cs={0};cs.sock=GNUNET_NETWORK_socket_create(AF_UNIX,SOCK_STREAM,0);assert(cs.sock);struct GNUNET_MQ_Handle*mq=queue();cs.mq=mq;mq->send_impl=&connection_client_send_impl;mq->impl_state=&cs;GNUNET_MQ_send(mq,envelope(168));
 send_results[0]=first;send_errors[0]=err;send_count=1;if(!(first<0&&err==EPIPE)&&first<20){send_results[1]=0;send_errors[1]=0;send_results[2]=-1;send_errors[2]=EAGAIN;send_results[3]=-1;send_errors[3]=EINTR;send_results[4]=20-(first>0?first:0);send_errors[4]=0;send_count=5;}
 size_t offset=0;for(unsigned i=0;i<send_count;i++){if(send_results[i]>0)offset+=send_results[i];deliver(cs.send_task,1);assert(cs.msg_off==offset);if(err==EPIPE){assert(GNUNET_MQ_get_length(mq)==1&&!mq->in_flight&&!inflight_calls&&!sent_calls&&!continue_calls&&error_calls==1);}else{assert(GNUNET_MQ_get_length(mq)==0&&sent_calls==1&&!error_calls);assert((offset==20)==(continue_calls==1));assert(mq->in_flight==(offset!=20));}printf("io|%s|%u|%zu|%u|%u|%u|%u|%u|%u\n",name,i,cs.msg_off,GNUNET_MQ_get_length(mq),mq->in_flight,inflight_calls,sent_calls,continue_calls,error_calls);}

 if(mq->send_task)deliver(mq->send_task,1);if(cs.send_task){GNUNET_SCHEDULER_cancel(cs.send_task);cs.send_task=NULL;}GNUNET_MQ_destroy(mq);GNUNET_NETWORK_socket_close(cs.sock);
}
